function readLink(text, start, definitions) {
  // Find the closing ] for [text]
  const closing = closingBracket(text, start + 1)
  if (closing === -1) return undefined

  const inner = text.slice(start + 1, closing)
  let pos = closing + 1

  // Check for (url) form
  if (pos < text.length && text[pos] === '(') {
    // Find the closing ), accounting for escapes
    let parenEnd = -1
    for (let i = pos + 1; i < text.length; i += 1) {
      if (text[i] === '\\') {
        i += 1
        continue
      }
      if (text[i] === ')') {
        parenEnd = i
        break
      }
    }
    if (parenEnd !== -1) {
      const urlRaw = text.slice(pos + 1, parenEnd).trim()
      // Unescape the URL
      let url = ''
      for (let i = 0; i < urlRaw.length; i += 1) {
        if (urlRaw[i] === '\\' && i + 1 < urlRaw.length && ESCAPABLE.includes(urlRaw[i + 1])) {
          url += urlRaw[i + 1]
          i += 1
          continue
        }
        url += urlRaw[i]
      }
      if (url.length > 0) {
        return { url, inner, next: parenEnd + 1 }
      }
    }
  }

  // Check for [label] or [] form
  if (pos < text.length && text[pos] === '[') {
    const refClose = closingBracket(text, pos + 1)
    if (refClose !== -1) {
      let label = text.slice(pos + 1, refClose)
      if (label === '') {
        // [] form - use inner text as label
        label = inner
      }
      const normalized = normalizeLabel(label)
      const definition = definitions.get(normalized)
      if (definition !== undefined) {
        return { url: definition.url, inner, next: refClose + 1 }
      }
      return undefined // Label not found
    }
  }

  return undefined
}"}

